import copy,hashlib,json,shutil
from pathlib import Path
from PIL import Image
D=Path(__file__).resolve().parent;R=D.parents[4];S=R/'stories/lion_and_mouse_v7';F=S/'review/scene_compositions/s08_scenes_r001'
def read(p):return json.loads(p.read_text())
def write(p,o):p.write_text(json.dumps(o,indent=2,ensure_ascii=False)+'\n')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def ref(p,**kw):return dict(path=str(p.relative_to(R)),sha256=sha(p),**kw)
def main():
 assert not (D/'OPERATION.json').exists();A=D/'owner_acceptance';A.mkdir(exist_ok=True);plan=read(S/'audio_visual_plan.json');before=copy.deepcopy(plan);lib=read(S/'character_performance_library.json');scenes=read(F/'SCENES.json');registry=read(S/'scene_composition_candidates_s08.json')
 write(A/'before_audio_visual_plan.json',before)
 if not (A/'REVIEW_CHANGES.json').exists():
  statement="ok now they passed. let's start creating now the poses for S09 to S11 please,"
  decisions=[]
  for row in scenes['outputs']:
   assert sha(R/row['path'])==row['sha256'];decisions.append(dict(image_id=row['image_id'],path=row['path'],sha256=row['sha256'],image_revision=row['image_revision'],reviewer='project_owner',scope='scene_depiction_only',statement=statement,all_image_ids=[v['image_id'] for v in row['all_audio_image_uses']]))
  ledger=A/'OWNER_SELECTION.json';write(ledger,{'images':decisions,'count':7,'image_associations':28,'scope':'Seven S08 scene depictions and their recorded uses only. Raw performance generation files, numerical anatomy and video remain separately scoped.'});changes=[]
  for row,decision in zip(scenes['outputs'],decisions):
   side=R/row['sidecar']['path'];assert sha(side)==row['sidecar']['sha256'];shutil.copy2(side,A/side.name);old=sha(side);approval=dict(decision,record=ref(ledger));data=read(side);data.update(status='owner_selected_scene_image',owner_approval=approval);write(side,data);row.update(status=data['status'],owner_approval=approval,sidecar=ref(side));changes.append({'path':str(side.relative_to(R)),'before_sha256':old,'after_sha256':sha(side)})
   for collection in [scenes['associations'],registry['images']]:
    for item in collection:
     if item['path']==row['path'] and item['sha256']==row['sha256']:item.update(status=data['status'],owner_approval=approval,sidecar=ref(side))
  write(F/'SCENES.json',scenes);write(S/'scene_composition_candidates_s08.json',registry);write(A/'REVIEW_CHANGES.json',changes)
 # A deterministic single-actor extraction for awake daylight resting Leo.
 # The selected clear-pair scene uses the raw paired raster unchanged at scale.
 # Remove Milo across the transparent inter-actor gap, not by repainting Leo.
 pair=lib['joint_performance_requirements']['milo_leo.s08.great_tree']['variants']['gentle_clear']['file'];source=R/pair['path'];assert sha(source)==pair['sha256'];im=Image.open(source).convert('RGBA');alpha=im.getchannel('A');assert alpha.crop((1240,0,1250,im.height)).getextrema()[1]<=1,'Review transparent separation before isolating Leo'
 out=R/'character/characters/lion_and_mouse_v7/Leo/poses/leo_rest_awake_clear_3q_r001_candidate.png';assert not out.exists();im.paste((0,0,0,0),(1245,0,im.width,im.height));im.save(out)
 (D/'receipts').mkdir();receipt=D/'receipts/local_leo_extraction.json';write(receipt,{'method':'owner-authorized local Pillow alpha extraction from pair used in selected S08 scene','source_pair':ref(source),'selected_scene':next(v for v in read(F/'SCENES.json')['outputs'] if v['source_variant']=='gentle_clear'),'erase_rectangle':[1245,0,im.width,im.height],'separation_check':'alpha at most 1/255 in x1240:1250, all rows; boundary inside near-transparent gap','preserve':'Source canvas unscaled; Leo silhouette left of x1245 retained exactly, boundary contains only <=1/255 alpha; removed separate Milo and right gap','provider_calls':0,'actual_cost':0,'approval_scope':'New extracted file remains candidate, not automatically performance-approved'})
 aid='leo.rest.awake.clear.3q';template=copy.deepcopy(lib['assets']['leo.rest.attentive.3q']);template.update(id=aid,family_id=aid,label='Awake lying Leo, clear front paw; exact local extraction from pair in owner-selected scene',parents=[]);variant=copy.deepcopy(template['variants']['default']);f=dict(ref(out),image_revision='r001',dimensions=list(im.size),alpha={'has_alpha':True,'extrema':list(im.getchannel('A').getextrema())})
 creation={'method':'local Pillow alpha extraction','inputs':[dict(ref(source),role='paired_pose_source',authority='exact depicted Leo raster; no identity or approval transfer')],'receipt':ref(receipt),'actual_cost':0};side=out.with_suffix('.json');write(side,{'asset_id':aid,'revision':'r001','image_revision':'r001','variant':'default','actor':'Leo','canonical':template['canonical'],'image_path':str(out.relative_to(R)),'image_sha256':sha(out),'dimensions':list(im.size),'alpha':f['alpha'],'creation':creation,'status':'candidate_pending_owner_review','owner_decision':None});f['sidecar']=ref(side);variant.update(status='candidate_pending_owner_review',file=f,creation=creation,owner_decision=None);template['variants']={'default':variant};lib['assets'][aid]=template
 write(D/'LOCAL_OUTPUTS.json',{'outputs':[dict(f,requirement_id=aid,variant='default',actors=['Leo'],audio_image_uses=['S09-L006-B01-I01','S09-L007-B01-I01'],receipt=ref(receipt))],'provider_calls':0})
 # Bind existing suitable walking/standing depictions explicitly, no duplicates.
 body_map={('milo.walk.homeward.3q','contact'):('milo.walk.screen_right.lightstep.3q','contact'),('milo.walk.homeward.3q','passing_step'):('milo.walk.screen_right.lightstep.3q','passing_step'),('milo.stand.attentive.3q','default'):('milo.decision.stationary.3q','forward')}
 # Leo's prior encouraging expression was a planning placeholder; traps call
 # for curiosity, alarm, effort, disbelief and concern rather than a warm smile.
 leo_faces={'S10-L001':'leo.expression.curious.s10.3q','S10-L002':'leo.expression.curious.s10.3q','S10-L003':'leo.expression.alert.s10.3q','S10-L004':'leo.expression.concerned.3q','S11-L001':'leo.expression.frustrated.3q','S11-L002':'leo.expression.frustrated.3q'}
 for aid,label in [('leo.expression.curious.s10.3q','Quiet curious attention toward leaves, not surprised or encouraging'),('leo.expression.alert.s10.3q','Alert concern as net drops, not exaggerated panic')]:
  a=copy.deepcopy(lib['assets']['leo.expression.concerned.3q']);a.update(id=aid,label=label);lib['assets'][aid]=a
 requirements=[]
 for line in plan['lines']:
  if line['audio_scene'] not in ['S09','S10','S11']:continue
  for b in line['beats']:
   for image in b['image_sequence']['images']:
    for actor,binding in image.get('performance',{}).items():
     key=(binding['pose_id'],binding['pose_variant'])
     if line['audio_scene']=='S09' and key in body_map:
      pose,name=body_map[key];binding.update(pose_id=pose,pose_variant=name,pose_revision=lib['assets'][pose]['revision'],pose_sha256=lib['assets'][pose]['variants'][name]['file']['sha256'])
     if line['line_id'] in ['S09-L006','S09-L007']:
      binding.update(pose_id='leo.rest.awake.clear.3q',pose_variant='default',pose_revision='r001',pose_sha256=f['sha256'])
     if actor=='Leo' and line['line_id'] in leo_faces:
      binding.update(expression_id=leo_faces[line['line_id']],expression_variant='default',expression_revision='r001',expression_sha256=None)
    requirements.append({'line_id':line['line_id'],'image_id':image['id'],'role':image['role'],'audio':line['audio'],'narration':line['text'],'action':b['action'],'location_view':image['location_view'],'state_ref':image['state'],'performance':image.get('performance',{}),'environment_only':not image.get('performance')})
 assert plan['world_states']==before['world_states'] and plan['world_events']==before['world_events'];assert [(l['line_id'],l['audio'],l['text']) for l in plan['lines']]==[(l['line_id'],l['audio'],l['text']) for l in before['lines']]
 write(S/'audio_visual_plan.json',plan);write(S/'character_performance_library.json',lib)
 requests=[]
 for actor,asset,variant,action,source_asset,source_variant in [
  ('Milo','milo.walk.careful.3q','contact','A careful homeward walking contact: three-quarter view toward screen-right, small deliberate step, near foot supporting in front, far foot trailing, naturally counter-swinging arms. Gaze angled down at the ground route ahead without changing skull anatomy. Soft relieved concentration, small closed-mouth smile, no hurry/panic. Continuous hip–thigh–knee–ankle construction, grey paws. This is a genuinely careful walk, not standing or tripping.','milo.walk.screen_right.lightstep.3q','contact'),
  ('Milo','milo.walk.careful.3q','opposite_contact','The distinct opposite-foot contact of a careful homeward walk in three-quarter screen-right view. Far leg now steps forward and near leg trails, with anatomically continuous hip/thigh/knee/ankle and corresponding opposite arm swing. Downward attention to the route, gentle relieved concentration and closed mouth. Keep same head/body/ear/cream-patch widths and lean design as the reference; do not duplicate the reference leg arrangement.','milo.walk.screen_right.lightstep.3q','opposite_contact'),
  ('Leo','leo.walk.notice.3q','contact','Leo walking quadruped in three-quarter screen-right view; a natural contact step with one front paw reaching forward and planted, diagonally coordinated hind support, other paws naturally spaced. Head angled only slightly downward to notice something among leaves ahead. Quiet curiosity, attentive brows, closed mouth, no encouraging grin or exaggerated surprise. Keep four anatomically continuous limbs and rounded clawless paws. No leaves/trigger/props in this body reference.','LeoCanonical','default'),
  ('Leo','leo.walk.notice.3q','passing_step','A distinct quadruped passing step of the same screen-right curious walk: supporting front leg beneath shoulder, opposite front paw lifting/passing forward, hind legs in coherent diagonal gait phase. Keep four connected limbs, mane/head/trunk/tail and rounded clawless paw design. Gaze gently downward toward something ahead among leaves, quiet curiosity, closed mouth. No actual leaves/trigger/props in the transparent pose.','LeoCanonical','default'),
  ('Leo','leo.net.grounded.3q','default','First settled-net construction anchor. Leo remains grounded in a three-quarter screen-right quadruped stance with ALL FOUR paws safely planted at the same support plane, body slightly braced, no hanging, rolling or full collapse. A single soft natural tan rope net drapes over crown/outer mane, shoulders, trunk and flanks, with one consistent diamond mesh and clearly connected rounded knots. Leave a stable generous opening so both eyes, nose and muzzle remain clear. The net is neither a neck noose nor a sack. No tight neck loop, injury, teeth or claws. Border/corner ropes come down to four identifiable grounded corner ends around the stance; no floating loose disconnected strands. All ropes intact, no torn mesh or breaking. Leo shows alert concern and puzzlement at being caught, not a cheerful grin or comic panic. This image proposes the net-on-body topology for later review; future tug/portrait/call variants must reuse its mesh, knot positions and facial opening, allowing only physically caused deformation. Do not add trees, overhead branches, floor or background; retain genuine transparency between mesh cells.','LeoCanonical','default')]:
  canonical=lib['assets'][asset]['canonical'];anno=S/'review/character_performance_consistency_r001/canonical_measurements_r001'/(actor.lower()+'_combined_annotated.jpg')
  refs=[dict(canonical,role='canonical_identity',authority='identity/anatomy/material/intrinsic palette'),ref(anno,role='canonical_measurement_annotation',authority='own-character visible surface ratios only, no printed guides')]
  if source_asset!='LeoCanonical':
   v=lib['assets'][source_asset]['variants'][source_variant];refs.insert(0,dict(v['file'],role='selected_pose_reference',authority='Milo anatomy/lean shape, projected head/torso/ears/paws and gait direction; requested new step/gaze may differ'))
  prompt='Create ONE reusable transparent '+actor+' performance candidate. '+action+' Each character keeps its own canonical anatomy: preserve skull/muzzle, eye size/spacing, ears/'+('mane curls and trunk' if actor=='Leo' else 'neck, lean torso, orange tail and cream patch')+', limb/paw widths and intrinsic felt colors. Use the attached canonical and that character’s own visible measurement guide; never apply Milo ratios to Leo or draw annotation marks. Milo upright comparable-view projected head fraction is 0.39 +/-0.01; bent or foreshortened measurements need separate comparison, not fabricated precision. No independent head/body/limb resizing. Full character and tail with generous margins, closed toothless mouth, natural soft neutral illumination, genuine transparent alpha. No scene, ground plane, cast shadow, text, icons or watermark. One output only. New pose, net design/contact and numerical anatomy remain subject to owner review.'
  out='character/characters/lion_and_mouse_v7/'+actor+'/'+('interactions' if 'net.' in asset else 'poses')+'/'+asset.replace('.','_')+'_'+variant+'_r001_candidate.png'
  uses=[r['image_id'] for r in requirements if any(v['pose_id']==asset and v['pose_variant']==variant for v in r['performance'].values())]
  requests.append({'sequence':len(requests)+1,'requirement_id':asset,'variant':variant,'actors':[actor],'output':out,'sidecar':out.replace('.png','.json'),'audio_image_uses':uses,'inputs':refs,'tool_arguments':{'prompt':prompt,'referenced_image_paths':[str(R/x['path']) for x in refs],'transparent_background':True}})
 for q in requests:
  assert not (R/q['output']).exists()
  for x in q['inputs']:assert sha(R/x['path'])==x['sha256']
 write(D/'OPERATION.json',{'schema':'feltwillow.performance-generation-proposal.v1','status':'prepared_pending_concrete_owner_approval','endpoint':'image_gen.imagegen','request_count':5,'outputs_per_request':1,'automatic_retries':0,'estimated_total_cost':None,'pricing':'Built-in current model/seed/per-image charge not exposed; cost unknown, not assumed free','scope':'Two careful Milo steps, two curious Leo steps, one grounded Leo/net construction anchor. No scene backgrounds, trigger/falling/tug/portrait/call followups before reviewed anchors; no audio/video.','requests':requests})
 write(D/'POSE_REQUIREMENTS.json',{'image_assignments':requirements,'reuse_existing':['S09 L001 existing Milo lightstep contact/passing with soft smile','S09 L005 existing stationary forward Milo depiction can cover familiar routines','S09 L006/L007 new zero-call exact awake-Leo extraction candidate, not sleeping Leo because persistent state explicitly says awake'],'environment_only':[r['image_id'] for r in requirements if r['environment_only']],'new_request_count':5,'held_followups':['Leo trigger approach/pressed after reviewed walking geometry','One connected net falling -> settled transition; stable overhead anchor geography belongs to future trap setup','Leo net tug rest/hold, retain all four paws grounded and connected rope topology','Leo trapped upper-body portrait family: disbelief, frustration, concern; same net facial opening','Leo head-up call with grounded paws, closed toothless narrator boundary mouth; explicit later audio treatment','Any additional Milo/Leo facial edits only if selected prepared pose acting does not fit narration'],'story_rules':'No new surprise/encouragement default on all shots; curiosity -> alert concern -> effort/frustration -> help-seeking. Net intact throughout S11, no rescue/breaking until later narrated events. Preserve same S10/S11 trap geography once scene setup is reviewed.'})
 (D/'REVIEW.md').write_text('# S09–S11 pose preparation\n\nS08’s seven scene depictions (28 recorded uses) selected at exact hashes. Three phases of work: S09 relieved/careful homeward Milo and ordinary routines; S10 curious walking Leo/trigger/net drop; S11 grounded struggle, disbelief/frustration and call for help. Environment-only time change/trigger insert/forest echo require no character pose.\n\nReuse reviewed Milo walking/standing references. One zero-call local awake-Leo extraction candidate is saved for S09 L006/L007; sleepy Leo would contradict the awake persistent state. The selected S08 scene grants depicted source authority, not automatic approval of this newly extracted file.\n\nConcrete first generation stage: **5 image_gen.imagegen requests**, two careful Milo contacts, two curious Leo walking steps, one grounded Leo/net construction anchor. One transparent output each, no retries, total cost unknown. Exact input paths/hashes, prompts and settings in [OPERATION.json](OPERATION.json). No submissions.\n\nReview the net anchor before deriving all falling/tug/portrait/call states: one connected mesh, stable knots/open face, all paws grounded, no neck snare, no torn rope, stable scene anchors later. Keep species-specific body/width/paw ratios and closed toothless still mouths. Further required phases are listed in [POSE_REQUIREMENTS.json](POSE_REQUIREMENTS.json); first five requests are not full S09–S11 completion. No full unit suite or Git publication.\n')
